(3956293, 564146, 57378, '<td valign="top">Interesting group of people - Like all the textures and the composition. Triumph? can''t see that really.</td>', 'Interesting group of people - Like all the textures and the composition. Triumph? can''t see that really.', '2007-08-01 06:43:21.000000', NULL, 1),
(3956299, 562706, 57378, '<td valign="top">Nice capture - Love the tones in this - Great sharpness where it needs to be and I hope this does well - I really like it - The one thing that could make this image a lot stronger and that would be with cropping - The horizon is far too centered and there is a lot of sky which this picture isn''t about - there is nothing in the sky of interest apart from the gull - I cropped it mid way down the sky from the top and it really gives this image more impact and helps us concentrate on the main subject - The swimmer - Still a great image</td>', 'Nice capture - Love the tones in this - Great sharpness where it needs to be and I hope this does well - I really like it - The one thing that could make this image a lot stronger and that would be with cropping - The horizon is far too centered and there is a lot of sky which this picture isn''t about - there is nothing in the sky of interest apart from the gull - I cropped it mid way down the sky from the top and it really gives this image more impact and helps us concentrate on the main subject - The swimmer - Still a great image', '2007-08-01 06:46:29.000000', NULL, 1),
(3956340, 563928, 62281, '<td valign="top">Meets the challenge perfectly, with no studio or model in sight 10</td>', 'Meets the challenge perfectly, with no studio or model in sight 10', '2007-08-01 07:19:45.000000', NULL, 1),
