(3976298, 563315, 60862, '<td valign="top">Fantastic composition and focus!</td>', 'Fantastic composition and focus!', '2007-08-07 02:46:53.000000', NULL, 1),
(3976299, 563893, 60862, '<td valign="top">Man, those acrobats just stun me.  Like this pose, they do things I wouldn''t believe if I hadn''t seen them myself.  Beautiful shot of them!</td>', 'Man, those acrobats just stun me.  Like this pose, they do things I wouldn''t believe if I hadn''t seen them myself.  Beautiful shot of them!', '2007-08-07 02:47:03.000000', NULL, 1),
