(3976386, 563895, 57032, '<td valign="top">Could be sharper in the face (eyes). Interesting take on the challenge, but perhaps a different composition would have worked better.</td>', 'Could be sharper in the face (eyes). Interesting take on the challenge, but perhaps a different composition would have worked better.', '2007-08-07 03:43:34.000000', NULL, 1),
(3976389, 563117, 57032, '<td valign="top">Good take on the challenge. Lots of noise, which is distracting, and much of the background is blown out.</td>', 'Good take on the challenge. Lots of noise, which is distracting, and much of the background is blown out.', '2007-08-07 03:45:31.000000', NULL, 1),
(3976391, 564605, 57032, '<td valign="top">A nice silhouette and interesting composition. The clouds are quite noisy. I don''t quite see how this fits the Triumph challenge.</td>', 'A nice silhouette and interesting composition. The clouds are quite noisy. I don''t quite see how this fits the Triumph challenge.', '2007-08-07 03:47:18.000000', NULL, 1),
(3976392, 563928, 57032, '<td valign="top">Nice timing, but much of the image is blown out and the contrast is a bit flat.</td>', 'Nice timing, but much of the image is blown out and the contrast is a bit flat.', '2007-08-07 03:47:44.000000', NULL, 1),
(3976393, 564248, 57032, '<td valign="top">A bit blurry. Great colour contrast.</td>', 'A bit blurry. Great colour contrast.', '2007-08-07 03:48:15.000000', NULL, 1),
(3976397, 564146, 57032, '<td valign="top">Good exposure, but I failed to see anything triumphant. Every person looked either disgusted or confused.</td>', 'Good exposure, but I failed to see anything triumphant. Every person looked either disgusted or confused.', '2007-08-07 03:49:26.000000', NULL, 1),
(3976398, 564418, 57032, '<td valign="top">Good capture of triumph, but the shadows are harsh, the faces could be crisper, and the contrast is a bit flat.</td>', 'Good capture of triumph, but the shadows are harsh, the faces could be crisper, and the contrast is a bit flat.', '2007-08-07 03:50:58.000000', NULL, 1),
(3976399, 564635, 57032, '<td valign="top">Good composition. The sky and some of the water is blown out, which is quite distracting.</td>', 'Good composition. The sky and some of the water is blown out, which is quite distracting.', '2007-08-07 03:51:42.000000', NULL, 1),
(3976401, 564636, 57032, '<td valign="top">A good B&amp;W, but there''s no sense of why he''s happy.</td>', 'A good B&W, but there''s no sense of why he''s happy.', '2007-08-07 03:52:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3976402, 562361, 57032, '<td valign="top">The signs in the front are a bit distracting. Perhaps a different composition (zoomed out a bit) would fare better.</td>', 'The signs in the front are a bit distracting. Perhaps a different composition (zoomed out a bit) would fare better.', '2007-08-07 03:53:08.000000', NULL, 1),
(3976404, 561647, 57032, '<td valign="top">Good positioning of the dog, but I couldn''t figure out *who* is on the way. The image could be sharper, and perhaps contrast boosted a bit.</td>', 'Good positioning of the dog, but I couldn''t figure out *who* is on the way. The image could be sharper, and perhaps contrast boosted a bit.', '2007-08-07 03:54:14.000000', NULL, 1),
(3976602, 561280, 29748, '<td valign="top">Wow, this is very noisy.  I would try reducing the ISO on your camera.  It also looks like you have a light flare.  Did you shoot this with the lens hood on?  If not try that.</td>', 'Wow, this is very noisy.  I would try reducing the ISO on your camera.  It also looks like you have a light flare.  Did you shoot this with the lens hood on?  If not try that.', '2007-08-07 09:29:02.000000', NULL, 1),
(3976604, 563313, 29748, '<td valign="top">Wow, this has some great clarity, and colors are very vibrant.</td>', 'Wow, this has some great clarity, and colors are very vibrant.', '2007-08-07 09:29:31.000000', NULL, 1),
(3976607, 562253, 29748, '<td valign="top">Wow, great colors and clarity.  the stop action is very nice.</td>', 'Wow, great colors and clarity.  the stop action is very nice.', '2007-08-07 09:30:20.000000', NULL, 1),
(3976610, 564323, 29748, '<td valign="top">Great timing.  What a beautiful scene.</td>', 'Great timing.  What a beautiful scene.', '2007-08-07 09:31:29.000000', NULL, 1),
(3976885, 563255, 59194, '<td valign="top">Great B&amp;W and textures.</td>', 'Great B&W and textures.', '2007-08-07 12:00:18.000000', NULL, 1),
(3976978, 562769, 19978, '<td valign="top">Sunrises and sunsets are a tough sell in most challenges. They''re shot often and as a result, there has to be something truly spectacular about them to make them stand out. Moreover, in the DPC Universe, there has to be some connection to the challenge. In this case, I''m afraid, you''ve got neither. It''s not a spectacular shot of a sunrise, nor is there any reasonable connection to the challenge other than your appending the word to the title.</td>', 'Sunrises and sunsets are a tough sell in most challenges. They''re shot often and as a result, there has to be something truly spectacular about them to make them stand out. Moreover, in the DPC Universe, there has to be some connection to the challenge. In this case, I''m afraid, you''ve got neither. It''s not a spectacular shot of a sunrise, nor is there any reasonable connection to the challenge other than your appending the word to the title.', '2007-08-07 12:26:26.000000', NULL, 1),
(3976982, 561658, 80878, '<td valign="top">The title should clerly be... Angry bird!</td>', 'The title should clerly be... Angry bird!', '2007-08-07 12:26:59.000000', NULL, 1),
