INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3985266, 562519, 19672, '<td valign="top">WOW....<br/> <br/>Uber-gorgeous...you can retire now!</td>', 'WOW.... Uber-gorgeous...you can retire now!', '2007-08-09 22:38:44.000000', NULL, 0),
(3985718, 562519, 60910, '<td valign="top">This shot is amazing!!  I myself have been doing the same thing with my hummingbirds, pre set manual focus, waiting, waiting, waiting, most of my 328 shots going to recycle bin with a few keepers.  It''s an inspiring shot for me to see and I KNOW how difficult these are to capture!  Congrats!!</td>', 'This shot is amazing!!  I myself have been doing the same thing with my hummingbirds, pre set manual focus, waiting, waiting, waiting, most of my 328 shots going to recycle bin with a few keepers.  It''s an inspiring shot for me to see and I KNOW how difficult these are to capture!  Congrats!!', '2007-08-10 00:41:01.000000', NULL, 0),
(3986338, 564543, 22872, '<td valign="top">Congratulations!!!! :)</td>', 'Congratulations!!!! :)', '2007-08-10 10:03:11.000000', NULL, 0),
(3986601, 564265, 60862, '<td valign="top">Well, I loved it - gave it a 7.  Yes, the processing is a little distracting, so it wasn''t a 10, but his expression, his pose, and the colors are all great!</td>', 'Well, I loved it - gave it a 7.  Yes, the processing is a little distracting, so it wasn''t a 10, but his expression, his pose, and the colors are all great!', '2007-08-10 12:11:08.000000', NULL, 0),
(3986703, 563640, 61818, '<td valign="top">In the end, the universe corrected the challenge and pushed this up to the blue where it belonged.  Grats again!!!</td>', 'In the end, the universe corrected the challenge and pushed this up to the blue where it belonged.  Grats again!!!', '2007-08-10 12:37:53.000000', NULL, 0),
